package com.universe.school.controller; import com.universe.global.common.ApiResponse; import com.universe.school.dto.request.*; import com.universe.school.dto.response.SchoolVerificationResponse; import com.universe.school.service.SchoolVerificationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/schools/verifications") @RequiredArgsConstructor public class SchoolVerificationController {private final SchoolVerificationService service; @PostMapping public ApiResponse<SchoolVerificationResponse> request(@Valid @RequestBody SchoolVerificationRequest r){return ApiResponse.success(service.request(r));} @PostMapping("/{verificationId}/confirm") public ApiResponse<SchoolVerificationResponse> confirm(@PathVariable Long verificationId,@Valid @RequestBody SchoolVerificationConfirmRequest r){return ApiResponse.success(service.confirm(verificationId,r));} @GetMapping("/me") public ApiResponse<SchoolVerificationResponse> me(){return ApiResponse.success(service.me());}}
